import type { IntentNode, ParsedIntentFile } from "../parser/intent.js";
import type { ParsedProfileFile, ProfileItem } from "../parser/profile.js";

const INTRO =
  "Who this project serves, and what the intents do for them. Generated by `@vaubaan/harness` from `docs/profiles/*.md` and `docs/intents/*.md`: edit those, not this file, then run `npx @vaubaan/harness update .`.";
const EMPTY =
  "No profile yet. The `intent-writer` skill writes the first one from the research you point it to.";

/**
 * `docs/profiles/README.md`: each profile with its status, the level-1
 * intents that name it as an actor, and under each pain and gain the
 * terminal intents that serve it (docs/spec/coding-agent-harness.md §9.1.4).
 */
export function buildProfilesIndex(
  profiles: ReadonlyArray<ParsedProfileFile>,
  intentFiles: ReadonlyArray<ParsedIntentFile> = [],
): string {
  const lines = ["# Profiles", "", INTRO];
  if (profiles.length === 0) lines.push("", EMPTY);
  const sortedIntents = [...intentFiles].sort((a, b) =>
    a.file < b.file ? -1 : a.file > b.file ? 1 : 0,
  );
  for (const profile of [...profiles].sort((a, b) => (a.file < b.file ? -1 : 1))) {
    const theirs = sortedIntents.filter((file) => file.meta?.actors.includes(profile.slug));
    lines.push(
      "",
      `## [${profile.title}](./${profile.file}) — ${profile.meta?.status ?? "hypothesis"}`,
      "",
    );
    lines.push(
      theirs.length
        ? `Intents: ${theirs.map((f) => `[${f.title}](../intents/${f.file})`).join(", ")}.`
        : "Intents: none names this profile yet.",
    );
    const served = (kind: "relieves" | "delivers", item: ProfileItem): string => {
      const by: string[] = [];
      for (const file of theirs) {
        for (const node of file.nodes as ReadonlyArray<IntentNode>) {
          if (node[kind].includes(item.slug)) {
            by.push(`[${node.title}](../intents/${file.file})`);
          }
        }
      }
      if (by.length) return by.join(", ");
      return kind === "relieves" ? "*no intent relieves it yet*" : "*no intent delivers it yet*";
    };
    if (profile.pains.length) {
      lines.push("", "Pains, most severe first:", "");
      for (const pain of profile.pains) {
        lines.push(`- **${pain.name}** (\`${pain.slug}\`) — ${served("relieves", pain)}`);
      }
    }
    if (profile.gains.length) {
      lines.push("", "Gains:", "");
      for (const gain of profile.gains) {
        lines.push(`- **${gain.name}** (\`${gain.slug}\`) — ${served("delivers", gain)}`);
      }
    }
  }
  return `${lines.join("\n")}\n`;
}
